
/* ---------- 3. СОБЫТИЯ ---------- */
const own = id => R(id).owner === 'byz';
function spawn(f, rid, comp, name, gen) {
  const a = addArmy(f, rid, comp, name);
  if (gen) a.gen = { name: gen[0], skill: gen[1] };
  return a;
}
function nearOf(rid, f) { // область фракции f рядом с rid (или сама rid)
  const n = NEIGH[rid].map(x => x.to).filter(x => R(x).owner === f);
  return n.length ? pick(n) : null;
}
function setOwner(rid, f) { const r = R(rid); if (r.owner === 'byz' && f !== 'byz') G.stats.lostR++; r.owner = f; r.siege = 0; dropGovernor(rid); }
function heroAt(name) { return G.heroes.find(h => h.status === 'court' && h.name.startsWith(name)); }
function addHist(name) { const d = HIST_HEROES.find(h => h[0] === name); if (!d || G.heroes.some(h => h.name === d[0])) return null; const h = makeHistHero(d); h.status = 'court'; const taken = new Set(courtHeroes().map(x => x.slot)); for (let s = 0; s < COUNCIL; s++) if (!taken.has(s)) { h.slot = s; break; } if (h.slot < 0) return null; G.heroes.push(h); (G.flags.usedHist = G.flags.usedHist || []).push(name); return h; }
function startCivilWar(name, regions, hostile, comp, gen) {
  G.flags.civilwar = true; G.fnames.rebel = name; G.fshort.rebel = name;
  G.factions.rebel.war = hostile; G.factions.rebel.truce = 0;
  regions.forEach(id => { if (own(id) && id !== 'konst') setOwner(id, 'rebel'); });
  const base = regions.find(id => R(id).owner === 'rebel');
  if (base && comp) spawn('rebel', base, comp, 'Войско: ' + name, gen);
}
function endCivilWar() {
  G.flags.civilwar = false;
  Object.values(G.regions).forEach(r => { if (r.owner === 'rebel') { r.owner = 'byz'; r.mood = 45; } });
  G.armies.filter(a => a.owner === 'rebel').forEach(a => { a.owner = 'byz'; a.gen = null; a.path = []; a.name = 'Бывшие мятежники'; });
  G.factions.rebel.war = true; G.fnames.rebel = 'Мятежники'; G.fshort.rebel = 'Мятежники';
}

