const PROLOGUE = { id: 'prologue', title: 'Пролог: кому править Городом?', text: 'Июль 1261 года. Отряд кесаря Алексея Стратигопула ночью вошёл в Константинополь через подземный ход у Источных ворот — и Город, пятьдесят семь лет бывший латинским, снова ромейский. Михаил Палеолог, соправитель юного Иоанна IV Ласкариса, спешит из Нимфея короноваться в Святой Софии. Но войско в Городе — у Стратигопула, а законный наследник — мальчик Ласкарис.',
  note: 'Исторически Стратигопул остался верен Михаилу VIII; тот короновался 15 августа 1261 года, а в Рождество ослепил Иоанна IV. Второй путь — альтернативная история.',
  opts: [
    { t: 'Михаил VIII Палеолог — новый василевс', h: 'Историческое начало. Сильнейший дипломат эпохи', fx: () => { G.path = 'michael'; log('15 августа 1261 года Михаил VIII Палеолог коронован в Святой Софии.', 'imp'); } },
    { t: 'Стратигопул свергает Палеолога и становится регентом при Иоанне IV', h: 'Престиж +4, Церковь +6, порядок −3. Свои события: судьба Михаила, совершеннолетие Иоанна IV', fx: () => {
      G.path = 'strat'; G.prestige += 4; G.church += 6; G.order -= 3;
      const s = heroAt('Алексей Стратигопул'); if (s) { heroGone(s, 'gone'); G.flags.usedHist = (G.flags.usedHist || []).filter(n => n !== 'Алексей Стратигопул'); G.heroes = G.heroes.filter(h => h !== s); }
      const j = heroAt('Иоанн Палеолог'); if (j) { j.loyalty = 40; j.desc += ' Брат свергнутого Михаила — служит, затаив обиду.'; }
      log('Кесарь Алексей Стратигопул взял власть в Городе и правит регентом при юном Иоанне IV Ласкарисе.', 'imp'); } } ] };
async function runPrologue() { if (G.fired.prologue) return; G.fired.prologue = true; await showEvent(PROLOGUE); }
function vespers(ch, cost) {
  G.treasury -= cost;
  if (rnd() < ch) {
    G.flags.vespers = true; G.anjou = 0; G.prestige += 8;
    G.armies.filter(a => a.owner === 'anjou').forEach(a => a.units = a.units.slice(0, 2));
    G.factions.anjou.weary += 20;
    log('Сицилия восстала! Флот Карла Анжуйского сожжён, поход на Константинополь отменён.', 'imp');
  } else {
    log('Восстание на Сицилии подавлено. Карл Анжуйский отплывает к нашим берегам!', 'imp');
    G.factions.anjou.war = true; G.factions.achaea.war = true;
    const at = R('dyrr').owner === 'anjou' ? 'dyrr' : (R('achaea').owner === 'achaea' ? 'achaea' : 'dyrr');
    if (!own(at)) { setOwner(at, 'anjou'); spawn('anjou', at, [['merc', 6], ['cav', 5], ['inf', 5], ['arch', 2]], 'Армада Карла', ['Карл Анжуйский', 4]); }
    G.flags.vespers = true; G.anjou = 0;
  }
}
function catalanRevolt() {
  G.flags.catalans = 'revolt';
  const a = G.armies.find(x => x.catalan && x.owner === 'byz');
  if (a) { a.owner = 'catalan'; a.gen = { name: 'Беренгер д\'Энтенса', skill: 4 }; a.path = []; a.region = own('thrace') ? 'thrace' : 'konst'; a.name = 'Каталонская месть'; if (a.region === 'konst') a.region = 'thrace'; }
  else spawn('catalan', 'thrace', [['merc', 7], ['cav', 2]], 'Каталонская месть', ['Беренгер д\'Энтенса', 4]);
  G.factions.catalan.war = true; G.order -= 6;
  log('Рожер де Флор убит в Адрианополе. Каталонская компания мстит — Фракия в огне!', 'imp');
}
function declareWarBy(f) { const F = G.factions[f]; F.war = true; F.truce = 0; const b = Object.values(G.regions).filter(r => r.owner === f && NEIGH[r.id].some(n => own(n.to)))[0]; if (b) spawn(f, b.id, [['inf', 4], ['cav', 3], ['arch', 2]]); log(`${fname(f)} начинает войну!`, 'imp'); }

